package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import org.hibernate.annotations.Fetch;
import org.hibernate.annotations.FetchMode;

/**
 * A person on a sheet: a name and a dated grade (A, B or C): each grade they are given is in force
 * from its from-date, the first from the beginning of time (see {@link #gradeOn}). The name is kept without the spaces around
 * it and is unique on the sheet without regard to case, compared through its {@link #keyOf key}.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "name_key", nullable = false)
    private String nameKey;

    /** The grades the person has been given, at most one per from-date. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonGrade> grades = new ArrayList<>();

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The holds the person has been put on: their OPEN and PENDING claims dated within one count in no
     * live total, unless a statement binds them. The same hold may be put on more than once. Loaded by
     * a sub-select, so it loads eagerly beside the grades. */
    @ElementCollection(fetch = FetchType.EAGER)
    @Fetch(FetchMode.SUBSELECT)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonHold> holds = new ArrayList<>();

    /** The person's own terms in days, in place of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, without surrounding spaces and in lower case, unique on the sheet; null
     * when they have none. */
    @Column(name = "contact")
    private String contact;

    /** Raised each time the person is saved. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        setName(name);
        this.grades.add(new PersonGrade(grade, null));
    }

    /** The form of a name that is unique on a sheet: without surrounding spaces, in lower case. */
    public static String keyOf(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name.trim();
        this.nameKey = keyOf(name);
    }

    /** The grades the person has been given, by from-date (the one with none first). */
    public List<PersonGrade> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** Gives the person {@code grade} from {@code from}, in place of one given from the same date. */
    public void setGrade(String grade, LocalDate from) {
        grades.removeIf(g -> from.equals(g.getFrom()));
        grades.add(new PersonGrade(grade, from));
    }

    /** The grade in force on {@code date}: the one with the latest from-date on or before it, or the
     * first one given when none has; the latest given when {@code date} is null. */
    public String gradeOn(LocalDate date) {
        PersonGrade best = null;
        for (PersonGrade g : getGrades()) {
            if (date != null && g.getFrom() != null && g.getFrom().isAfter(date)) continue;
            best = g;
        }
        return best == null ? null : best.getGrade();
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The form a contact is kept in: without surrounding spaces, in lower case; null for a blank one. */
    public static String contactOf(String contact) {
        if (contact == null || contact.isBlank()) return null;
        return contact.trim().toLowerCase(Locale.ROOT);
    }

    public String getContact() {
        return contact;
    }

    /** Gives the person {@code contact} (none when blank), kept in its {@link #contactOf stored form}. */
    public void setContact(String contact) {
        this.contact = contactOf(contact);
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Retired as soon as a retirement date is set, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person's retirement date is reached on {@code today}: on or after it. */
    public boolean isRetiredOn(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }

    /** The holds the person has been put on, by from-date. */
    public List<PersonHold> getHolds() {
        return holds.stream()
                .sorted(Comparator.comparing(PersonHold::getFrom)
                        .thenComparing(PersonHold::getTo, Comparator.nullsLast(Comparator.naturalOrder())))
                .toList();
    }

    /** Puts the person on {@code hold}. */
    public void addHold(PersonHold hold) {
        holds.add(hold);
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether {@code date} falls within any of the person's holds. */
    public boolean isHeldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Refuses a claim dated {@code date} when it falls after the person's retirement date. */
    public void requireClaimable(LocalDate date) {
        if (retiredFrom != null && date.isAfter(retiredFrom)) {
            throw new PersonRetiredException();
        }
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The people kept on each sheet. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final SheetService sheetService;
    private final PersonPatronRepository patrons;
    private final PersonWatchRepository watches;

    public PersonService(PersonRepository people, SheetRepository sheets, Audit audit, RollupService rollup,
            SheetService sheetService, PersonPatronRepository patrons, PersonWatchRepository watches) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
        this.sheetService = sheetService;
    }

    /** The sheet's people in the order they were added. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional(readOnly = true)
    public Person get(String sheetId, long personId) {
        return people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
        return add(sheetId, user, name, grade, terms, null);
    }

    /** Adds a person with their own terms (none when null) and contact (none when blank); refused when
     * another person on the sheet has the name or the contact. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
        requireFree(sheetId, name, null);
        requireContactFree(sheetId, contact, null);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person created = new Person(sheetId, name, grade);
        created.setTerms(terms);
        created.setContact(contact);
        Person person = people.saveAndFlush(created);
        List<String> fields = new ArrayList<>(List.of("name=" + person.getName(), "grade=" + grade));
        if (terms != null) fields.add("terms=" + terms);
        if (person.getContact() != null) fields.add("contact=" + person.getContact());
        audit.change("PERSON_ADDED", sheetId, user, fields.toArray(String[]::new));
        rollup.recordSince(sheetId, user, before);
        return person;
    }

    /** The sheet's today; null when the sheet has never been loaded. */
    @Transactional(readOnly = true)
    public LocalDate today(String sheetId) {
        return sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
    }

    /** Saves the person as edited from {@code version}, giving them {@code grade} from {@code gradeFrom}
     * (the sheet's today when left out) and keeping the grades given from other dates; refused when they
     * have been saved since. The person's own terms become {@code terms} (none when null), and their
     * contact {@code contact} (none when blank), refused when another person on the sheet has it. */
    @Transactional
    public Person update(String sheetId, String user, long personId, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (person.getVersion() != version) {
            throw new PersonStaleException(person);
        }
        requireFree(sheetId, name, person.getId());
        requireContactFree(sheetId, contact, person.getId());
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate today = sheetService.today(sheetId);
        person.setName(name);
        person.setGrade(grade, gradeFrom != null ? gradeFrom : today);
        boolean termsChanged = !Objects.equals(person.getTerms(), terms);
        person.setTerms(terms);
        boolean contactChanged = !Objects.equals(person.getContact(), Person.contactOf(contact));
        person.setContact(contact);
        people.flush();
        List<String> fields = new ArrayList<>(List.of("name=" + person.getName(), "grade=" + person.gradeOn(today)));
        if (termsChanged) fields.add("terms=" + (terms == null ? "" : terms));
        if (contactChanged) fields.add("contact=" + (person.getContact() == null ? "" : person.getContact()));
        audit.change("PERSON_EDITED", sheetId, user, fields.toArray(String[]::new));
        rollup.recordSince(sheetId, user, before);
        return person;
    }

    /** Retires the person from {@code from} (the sheet's today when left out); the figures it moves are
     * recorded as {@code user}'s change. */
    @Transactional
    public Person retire(String sheetId, String user, long personId, LocalDate from) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        LocalDate dated = from != null ? from : sheetService.today(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        person.setRetiredFrom(dated);
        people.flush();
        audit.change("PERSON_RETIRED", sheetId, user, "name=" + person.getName(), "from=" + dated);
        rollup.recordSince(sheetId, user, before);
        return person;
    }

    /** Puts the person on a hold from {@code from} (the sheet's today when left out) to {@code to}
     * (no end when left out); refused when it would end before it starts. The same hold may be put on
     * again. A hold ends on its to-date: there is no release. */
    @Transactional
    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        LocalDate dated = from != null ? from : sheetService.today(sheetId);
        if (dated == null || (to != null && to.isBefore(dated))) {
            throw new PersonHoldException();
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        person.addHold(new PersonHold(dated, to));
        people.flush();
        audit.change("PERSON_HELD", sheetId, user, "name=" + person.getName(), "from=" + dated);
        rollup.recordSince(sheetId, user, before);
        return person;
    }

    /** The sheet's patrons in the order they were named. */
    @Transactional(readOnly = true)
    public List<PersonPatron> patrons(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Names another person on the sheet as the person's patron; refused for the person themselves
     * and for one they have already named. */
    @Transactional
    public PersonPatron addPatron(String sheetId, String user, long personId, long patronId) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        Person patron = people.findByIdAndSheetId(patronId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (person.getId().equals(patron.getId()) || patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw new PersonPatronException();
        }
        PersonPatron added = patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
        audit.change("PATRON_ADDED", sheetId, user, "name=" + person.getName(), "patron=" + patron.getName());
        return added;
    }

    /** The ids of the people the user watches on the sheet, in the order they started watching. */
    @Transactional(readOnly = true)
    public List<Long> watched(String sheetId, String user) {
        return watches.findBySheetIdAndUserOrderByIdAsc(sheetId, user).stream().map(PersonWatch::getPersonId).toList();
    }

    /** Starts (on) or stops (off) the user watching the person; refused when they already do, or
     * do not. */
    @Transactional
    public Person watch(String sheetId, String user, long personId, boolean on) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        var current = watches.findByPersonIdAndUser(person.getId(), user);
        if (on == current.isPresent()) throw new PersonWatchException();
        if (on) {
            watches.saveAndFlush(new PersonWatch(sheetId, person.getId(), user));
        } else {
            watches.delete(current.get());
            watches.flush();
        }
        audit.change(on ? "PERSON_WATCHED" : "PERSON_UNWATCHED", sheetId, user, "name=" + person.getName());
        return person;
    }

    /** Refuses a name another person on the sheet (other than {@code self}) already has. */
    private void requireFree(String sheetId, String name, Long self) {
        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
                .filter(other -> !other.getId().equals(self))
                .ifPresent(other -> {
                    throw new PersonNameTakenException();
                });
    }

    /** Refuses a contact another person on the sheet (other than {@code self}) already has; a blank
     * contact is none, and is never refused. */
    private void requireContactFree(String sheetId, String contact, Long self) {
        String kept = Person.contactOf(contact);
        if (kept == null) return;
        people.findBySheetIdAndContact(sheetId, kept)
                .filter(other -> !other.getId().equals(self))
                .ifPresent(other -> {
                    throw new PersonContactTakenException();
                });
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.AsOfGuard;
import net.officefloor.hq.app.history.SheetHistory;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** The people on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** A grade a person was given and the date it is in force from (null: the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
        public static GradeView of(PersonGrade grade) {
            return new GradeView(grade.getGrade(), grade.getFrom());
        }
    }

    /** A hold a person was put on, from {@code from} to {@code to} (both included; null: no end). */
    public record HoldView(LocalDate from, LocalDate to) {
        public static HoldView of(PersonHold hold) {
            return new HoldView(hold.getFrom(), hold.getTo());
        }
    }

    /** A person: the grade in force on the sheet's {@code today}, and every grade they were given by
     * from-date; {@code retiredFrom} is null while they are not retired; {@code held} is whether they
     * have any hold, listed in {@code holds} by from-date. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version,
            boolean retired, LocalDate retiredFrom, boolean held, List<HoldView> holds, Integer terms,
            String contact) {
        public static PersonView of(Person person, LocalDate today) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(GradeView::of).toList(), person.getVersion(),
                    person.isRetired(), person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(HoldView::of).toList(), person.getTerms(),
                    person.getContact());
        }
    }

    /** A patron a person has named. */
    public record PatronView(long id, long personId, long patronId) {
        public static PatronView of(PersonPatron patron) {
            return new PatronView(patron.getId(), patron.getPersonId(), patron.getPatronId());
        }
    }

    /** The person to be named as a patron. */
    public record PatronRequest(@NotNull Long patronId) {
    }

    /** The date a person is retired from (the sheet's today when left out). */
    public record RetireRequest(LocalDate from) {
    }

    /** A hold to put a person on: from {@code from} (the sheet's today when left out) to {@code to}
     * (no end when left out). */
    public record HoldRequest(LocalDate from, LocalDate to) {
    }

    /** A person's name (not blank; kept without the spaces around it and unique on the sheet
     * without regard to case) and grade, one of A, B or C, given from {@code gradeFrom} on a save (the
     * sheet's today when left out; a person's first grade applies from the beginning of time), and
     * their own terms, a whole number of days, 0 or more (blank or null for none), and their contact
     * (kept without the spaces around it, in lower case, and unique on the sheet; blank or null for
     * none). */
    public record PersonRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @Pattern(regexp = "\\s*(\\d{1,4})?\\s*") String terms,
            Long version,
            @Size(max = 200) String contact) {
        Integer termsValue() {
            return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
        }
    }

    /** A grade to give the people {@code personIds} together, from {@code from} (the sheet's today when
     * left out). */
    public record BulkGradeRequest(@NotNull @Size(max = 1000) List<@NotNull Long> personIds,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate from) {
    }

    /** How a bulk grade went: how many people it changed, and those people. */
    public record BulkGradeView(int graded, List<PersonView> people) {
    }

    /** A save refused because the person was saved by someone else since the editor loaded them:
     * the person as now stored. */
    public record StaleView(String error, PersonView current) {
    }

    /** A save refused for a reason the form tells apart: {@code contact-taken}. */
    public record RefusedView(String error) {
    }

    private final PersonService service;

    private final PersonBulkService bulk;

    private final SheetHistory history;

    public PersonController(PersonService service, PersonBulkService bulk, SheetHistory history) {
        this.service = service;
        this.bulk = bulk;
        this.history = history;
    }

    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.read(sheetId.trim(), asOf).people().stream().map(person -> PersonView.of(person, asOf))
                    .toList();
        }
        LocalDate today = service.today(sheetId.trim());
        return service.list(sheetId.trim()).stream().map(person -> PersonView.of(person, today)).toList();
    }

    @GetMapping("/patrons")
    public List<PatronView> patrons(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        List<PersonPatron> patrons = asOf == null ? service.patrons(sheetId.trim())
                : history.read(sheetId.trim(), asOf).patrons();
        return patrons.stream().map(PatronView::of).toList();
    }

    @PostMapping("/{personId}/patrons")
    @ResponseStatus(HttpStatus.CREATED)
    public PatronView addPatron(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PatronRequest request) {
        return PatronView.of(service.addPatron(sheetId.trim(), user.trim(), personId, request.patronId()));
    }

    /** The ids of the people the signed-in user watches. */
    @GetMapping("/watched")
    public List<Long> watched(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) return history.read(sheetId.trim(), asOf).watchedBy(user.trim());
        return service.watched(sheetId.trim(), user.trim());
    }

    @PostMapping("/{personId}/watch")
    public PersonView watch(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(sheetId, service.watch(sheetId.trim(), user.trim(), personId, true));
    }

    @DeleteMapping("/{personId}/watch")
    public PersonView unwatch(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(sheetId, service.watch(sheetId.trim(), user.trim(), personId, false));
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PersonRequest request) {
        return view(sheetId, service.add(sheetId.trim(), user.trim(), request.name(), request.grade(),
                request.termsValue(), request.contact()));
    }

    @PutMapping("/{personId}")
    public PersonView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PersonRequest request) {
        if (request.version() == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "version is required");
        }
        try {
            return view(sheetId, service.update(sheetId.trim(), user.trim(), personId, request.version(),
                    request.name(), request.grade(), request.gradeFrom(), request.termsValue(), request.contact()));
        } catch (ObjectOptimisticLockingFailureException e) {
            // Another save of the person committed while this one was under way.
            throw new PersonStaleException(service.get(sheetId.trim(), personId));
        }
    }

    @PostMapping("/bulk-grade")
    public BulkGradeView bulkGrade(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkGradeRequest request) {
        List<Person> changed = bulk.grade(sheetId.trim(), user.trim(), request.personIds(), request.grade(),
                request.from());
        return new BulkGradeView(changed.size(), changed.stream().map(p -> view(sheetId, p)).toList());
    }

    @PostMapping("/{personId}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) RetireRequest request) {
        return view(sheetId, service.retire(sheetId.trim(), user.trim(), personId,
                request == null ? null : request.from()));
    }

    @PostMapping("/{personId}/hold")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) HoldRequest request) {
        return view(sheetId, service.hold(sheetId.trim(), user.trim(), personId,
                request == null ? null : request.from(), request == null ? null : request.to()));
    }

    @ExceptionHandler(PersonContactTakenException.class)
    public ResponseEntity<RefusedView> contactTaken() {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new RefusedView("contact-taken"));
    }

    @ExceptionHandler(PersonStaleException.class)
    public ResponseEntity<StaleView> stale(PersonStaleException e) {
        Person current = e.getCurrent();
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(new StaleView("stale", PersonView.of(current, service.today(current.getSheetId()))));
    }

    /** The person as the sheet shows them on its today. */
    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, service.today(sheetId.trim()));
    }
}
